import {STATIONS} from './rewards-core.js';

// Map includes the courtyard and residential paths: x -63..55, z -92..180.
export function installParkMap({pause,guideTo,rewards,guideToPoint=()=>{},destinations=()=>[]}){
 const $=s=>document.querySelector(s),style=document.createElement('link');style.rel='stylesheet';style.href='park-map.css';document.head.append(style);
 const button=document.createElement('button');button.textContent='Park map';button.id='mapButton';$('nav').append(button);
 const dialog=document.createElement('dialog');dialog.id='parkMap';dialog.setAttribute('aria-labelledby','mapTitle');
 dialog.innerHTML='<div class="map-heading"><div><span class="label">EXPLORE KROWNLANDIA</span><h2 id="mapTitle">Your park map</h2></div><button id="mapClose">Close</button></div><p id="mapSummary"></p><div class="map-layout"><div id="mapDrawing" aria-label="Map of the courtyard and rewards stations"><svg viewBox="-63 -92 118 272" aria-hidden="true"><rect x="-63" y="-92" width="118" height="272" fill="#294d43"/><path d="M0 37V-79 M-38 -25H0 M0 -50H40 M-30 -25V-35" fill="none" stroke="#c6b990" stroke-width="7"/><circle cx="0" cy="-35" r="17" fill="#c6b990"/><circle cx="0" cy="-35" r="6.6" fill="#58aebc" stroke="#ead9ad" stroke-width="1"/><ellipse cx="24" cy="-51" rx="5" ry="5" fill="#58aebc"/><rect x="-14" y="-90" width="28" height="9" rx="2" fill="#d9cba4"/><path d="M-8 14H8" stroke="#f1c962" stroke-width="3"/><rect x="-30" y="-22" width="12" height="8" fill="#94b9be"/><rect x="18" y="-22" width="12" height="8" fill="#ed80b1"/><path d="M-32 -36L-43 -42 -45 -54 -40 -65 -29 -67 -22 -57 -24 -44Z" fill="#183c43" stroke="#e8bd67" stroke-width="1"/></svg><span id="mapVisitor" aria-label="Your position">▲</span></div><div id="mapLocations"></div></div><p class="map-note">Numbers mark rewards stations. Select a destination for a direction and distance while you walk. Guidance points toward the station; follow the paths around obstacles.</p>';
 document.body.append(dialog);let snapshot={x:0,z:30,yaw:0},selected=null,view='courtyard',rewardsOnly=false;
 const courtyardDrawing="<svg viewBox=\"-63 -92 118 272\" aria-hidden=\"true\"><rect x=\"-63\" y=\"-92\" width=\"118\" height=\"272\" fill=\"#294d43\"/><path d=\"M0 37V-79 M-38 -25H0 M0 -50H40 M-30 -25V-35\" fill=\"none\" stroke=\"#c6b990\" stroke-width=\"7\"/><circle cx=\"0\" cy=\"-35\" r=\"17\" fill=\"#c6b990\"/><circle cx=\"0\" cy=\"-35\" r=\"6.6\" fill=\"#58aebc\" stroke=\"#ead9ad\" stroke-width=\"1\"/><ellipse cx=\"24\" cy=\"-51\" rx=\"5\" ry=\"5\" fill=\"#58aebc\"/><rect x=\"-14\" y=\"-90\" width=\"28\" height=\"9\" rx=\"2\" fill=\"#d9cba4\"/><path d=\"M-8 14H8\" stroke=\"#f1c962\" stroke-width=\"3\"/><rect x=\"-30\" y=\"-22\" width=\"12\" height=\"8\" fill=\"#94b9be\"/><rect x=\"18\" y=\"-22\" width=\"12\" height=\"8\" fill=\"#ed80b1\"/><path d=\"M-32 -36L-43 -42 -45 -54 -40 -65 -29 -67 -22 -57 -24 -44Z\" fill=\"#183c43\" stroke=\"#e8bd67\" stroke-width=\"1\"/></svg>";
 const safariDrawing='<svg viewBox="38 -88 90 85" aria-hidden="true"><rect x="38" y="-88" width="90" height="85" fill="#69774a"/><path d="M48 -28L64 -24 87 -26 105 -43 95 -66 70 -65 55 -48Z" fill="none" stroke="#dec28d" stroke-width="2.2" stroke-linejoin="round"/><ellipse cx="87" cy="-15" rx="6" ry="5" fill="#699aab"/><ellipse cx="70" cy="-77" rx="6" ry="3" fill="#699aab"/><ellipse cx="61" cy="-44" rx="6" ry="5" fill="#699aab"/><path d="M97 -79L100 -83 105 -78 101 -75Z" fill="#ac9b80"/><circle cx="65" cy="-15" r="7" fill="#829552"/><circle cx="116" cy="-42" r="8" fill="#a8ac68"/><circle cx="48" cy="-28" r="2" fill="#f8df96"/></svg>';
 const habitats=[['Acacia savanna','Giraffes',65,-15],['The waterhole','Elephants',87,-15],['Open grassland','Zebras',116,-42],['Rocky savanna','Lions',102,-77],['Riverbank','Hippos',70,-77],['Shallow wetlands','Flamingos',61,-44]];
 const tabs=document.createElement('div');tabs.id='mapViews';for(const [id,title] of [['courtyard','Park & villages'],['safari','Safari route']]){const tab=document.createElement('button');tab.id='mapView'+id;tab.textContent=title;tab.onclick=()=>{view=id;render();};tabs.append(tab);}dialog.append(tabs);

 const searchBox=document.createElement('div');searchBox.id='mapSearchBox';const searchLabel=document.createElement('label');searchLabel.htmlFor='mapSearch';searchLabel.textContent='Find a destination';const search=document.createElement('input');search.id='mapSearch';search.type='search';search.placeholder='Try coffee, home, lounge or picnic';search.value='';const clear=document.createElement('button');clear.id='mapSearchClear';clear.textContent='Clear search';const count=document.createElement('p');count.id='mapSearchCount';count.setAttribute('role','status');search.setAttribute('aria-describedby','mapSearchCount');const scenic=document.createElement('button');scenic.id='mapScenicSeats';scenic.textContent='Scenic seats';scenic.onclick=()=>{rewardsOnly=false;search.value='scenic';render();};const collect=document.createElement('button');collect.id='mapCollectRewards';collect.textContent='Rewards to collect';collect.onclick=()=>{rewardsOnly=!rewardsOnly;search.value='';render();};const shortcuts=document.createElement('div');shortcuts.id='mapShortcuts';shortcuts.append(scenic,collect);searchBox.append(searchLabel,search,clear,shortcuts,count);dialog.append(searchBox);search.oninput=()=>render();clear.onclick=()=>{search.value='';rewardsOnly=false;render();search.focus();};
 const normalize=value=>value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/['’]/g,'');
 const position=(node,x,z)=>{node.style.left=((view==='safari'?(x-38)/90:(x+63)/118)*100)+'%';node.style.top=((view==='safari'?(z+88)/85:(z+92)/272)*100)+'%';};
 function render(){
  const query=normalize(search.value.trim()),matches=text=>query.split(/\s+/).every(word=>normalize(text).includes(word));
  searchBox.hidden=view==='safari';clear.hidden=!query&&!rewardsOnly;clear.textContent=rewardsOnly?'Clear search and filter':'Clear search';collect.setAttribute('aria-pressed',String(rewardsOnly));scenic.setAttribute('aria-pressed',String(query==='scenic'&&!rewardsOnly));dialog.classList.toggle('map-searching',(!!query||rewardsOnly)&&view!=='safari');let resultCount=0;
  const st=rewards();$('#mapSummary').textContent=st.visits+' of '+STATIONS.length+' stations visited · '+st.points+' points';
  const list=$('#mapLocations');list.replaceChildren();
  // Recreate markers only when the dialog opens; movement updates the visitor alone.
  for(const node of markers)node.remove();markers=[];
  $('#mapDrawing').innerHTML=(view==='safari'?safariDrawing:courtyardDrawing.replace('</svg>','<rect x="-52" y="132" width="6" height="42" fill="#58aebc"/><path d="M0 40V176 M-46 76H46 M-18 116H35 M7 96V136H0 M25 128V140H0 M0 161H50 M-18 160H0 M-57 130V176 M-57 172.5H-43 M-43 132V177" stroke="#c6b990" stroke-width="4" fill="none"/><path d="M-47 64h36v8h-36z M11 64h36v8H11z M-18 104h36v8h-36z M10.5 149h37v8h-37z" fill="#ecd2a2"/></svg>').replace('</svg>','<circle cx="39" cy="-62" r="9" fill="#ae2442" stroke="#fff0cf" stroke-width="2"/><path d="M39 -53V-50" stroke="#e5b553" stroke-width="3"/></svg>'))+'<span id="mapVisitor" aria-label="Your position">▲</span>';
  $('#mapDrawing').style.aspectRatio=view==='safari'?'90 / 85':'118 / 272';$('#mapDrawing').setAttribute('aria-label',view==='safari'?'Safari habitats and ride route':'Courtyard and rewards stations');
  for(const id of ['courtyard','safari'])$('#mapView'+id).setAttribute('aria-pressed',String(view===id));
  $('#parkMap .map-note').textContent=view==='safari'?'The line shows the safari route. Numbers mark animal habitats. The white arrow is your position when you are in this area. Open the map during the ride to pause and check your progress.':'Numbers mark rewards stations. Select a destination for walking directions. Distances are direct estimates; follow the paths around obstacles.';
  if(view==='safari'){
   const ride=snapshot.safari,seen=ride?.active?Math.min(6,Math.max(0,ride.stop+(ride.phase==='stop'?1:0))):st.done.includes('safari-complete')?6:0;
   $('#mapSummary').textContent=(ride?.active?'This safari: ':'Safari progress: ')+seen+' / 6 habitats reached';
   habitats.forEach(([name,animal,x,z],i)=>{const marker=document.createElement('span');marker.className='map-marker'+(i<seen?' visited':'');marker.textContent=String(i+1);position(marker,x,z);$('#mapDrawing').append(marker);markers.push(marker);const row=document.createElement('div');row.className='map-location habitat-row';const title=document.createElement('strong');title.textContent=(i+1)+'. '+name;const info=document.createElement('span');info.textContent=animal+' · '+(i<seen?'Reached':'Ahead on the route');row.append(title,info);list.append(row);});
   if(!ride?.active){const go=document.createElement('button');go.id='mapSafariEntrance';go.textContent='Guide me to the safari entrance';go.onclick=()=>{guideTo('safari');dialog.close();};list.append(go);}update(snapshot);return;
  }
  const distance=p=>Math.hypot(p.x-snapshot.x,p.z-snapshot.z),distanceLabel=p=>'About '+Math.round(distance(p))+' m away';
  const stations=STATIONS.map((s,i)=>({s,i}));if(rewardsOnly)stations.sort((a,b)=>distance(a.s)-distance(b.s)||a.i-b.i);
  stations.forEach(({s,i})=>{
   if(!matches(s.name+' rewards station'))return;
   const visited=st.claims.includes(s.id+':arrival'),taskDone=st.claims.includes(s.id+':task'),ready=st.done.includes(s.task.id)&&!taskDone;
   if(rewardsOnly&&visited&&!ready)return;resultCount++;
   const choose=()=>{selected=s.id;guideTo(s.id);dialog.close();};
   const marker=document.createElement('button');marker.className='map-marker'+(visited?' visited':'');marker.textContent=String(i+1);marker.setAttribute('aria-label',s.name+(visited?', visited':'')+'. Guide me');marker.onclick=choose;position(marker,s.x,s.z);$('#mapDrawing').append(marker);markers.push(marker);
   const row=document.createElement('button');row.id='mapGo-'+s.id;row.className='map-location';row.onclick=choose;
   const name=document.createElement('strong');name.textContent=(i+1)+'. '+s.name;
   const detail=document.createElement('span');detail.textContent=distanceLabel(s)+' · '+(visited?'Arrival collected':'Arrival +'+s.arrival)+' · '+(taskDone?'Task collected':ready?'Task ready: +'+s.task.points:'Task +'+s.task.points);
   row.append(name,detail);list.append(row);
  });
  if(query&&!rewardsOnly)for(const place of destinations().filter(p=>matches(p.name+' '+p.kind+' '+(p.keywords||''))).sort((a,b)=>distance(a)-distance(b))){resultCount++;const choose=()=>{selected=place.id;guideToPoint({x:place.x,z:place.z,name:place.name});dialog.close();};const row=document.createElement('button');row.id='mapGo-'+place.id;row.className='map-location';row.onclick=choose;const name=document.createElement('strong');name.textContent=place.name;const detail=document.createElement('span');detail.textContent=place.kind+' · '+distanceLabel(place)+' · Walking directions'+(place.detail?' · '+place.detail:'');row.append(name,detail);list.append(row);const marker=document.createElement('button');marker.className='map-marker';marker.textContent=place.kind[0];marker.setAttribute('aria-label',place.name+'. Walking directions');marker.onclick=choose;position(marker,place.x,place.z);$('#mapDrawing').append(marker);markers.push(marker);}
  count.textContent=rewardsOnly?(resultCount?resultCount+' station'+(resultCount===1?'':'s')+' with arrival points or completed-task points to collect. Nearest first; distances are direct estimates, and walking routes may be longer.':query?'No rewards match this search. Clear search to see all stations.':'No rewards ready to collect. Complete more activities to unlock task points.'):query?(resultCount?resultCount+' matching destination'+(resultCount===1?'':'s'):'No destinations found. Try a place name, home, lounge or picnic, or clear the search.'):'Search destinations, find Scenic seats, or choose Rewards to collect.';
  update(snapshot);
 }
 let markers=[];
 function open(){pause();view=snapshot.safari?.active?'safari':'courtyard';render();dialog.showModal();}
 function update(state){snapshot=state;const visitor=$('#mapVisitor');visitor.hidden=view==='safari'?(state.x<38||state.x>128||state.z<-88||state.z>-3):(state.x<-63||state.x>55||state.z<-92||state.z>180);position(visitor,state.x,state.z);visitor.style.transform='translate(-50%,-50%) rotate('+(-state.yaw*180/Math.PI)+'deg)';}
 button.onclick=open;$('#mapClose').onclick=()=>dialog.close();
 return {open,update,get isOpen(){return dialog.open},get selected(){return selected}};
}
